Here's a practical approach to implement location-based greetings using different methods, along with code examples:

## Method 1: IP-Based Geolocation (Easiest)

```javascript
// Using a free geolocation API
async function getLocationBasedGreeting() {
    try {
        // Using ipapi.co (free tier available)
        const response = await fetch('https://ipapi.co/json/');
        const data = await response.json();
        const countryCode = data.country_code;

        return getGreetingByCountry(countryCode);
    } catch (error) {
        console.warn('Error getting location:', error);
        return 'Hello'; // Default fallback
    }
}

function getGreetingByCountry(countryCode) {
    const greetings = {
        'JP': 'Konnichiwa',      // Japan
        'BR': 'Olá',             // Brazil
        'FR': 'Bonjour',         // France
        'DE': 'Hallo',           // Germany
        'ES': 'Hola',            // Spain
        'IT': 'Ciao',            // Italy
        'RU': 'Privet',          // Russia
        'CN': 'Nǐ hǎo',          // China
        'KR': 'Annyeonghaseyo',  // South Korea
        'SA': 'As-salamu alaykum', // Saudi Arabia
        'IN': 'Namaste'          // India
    };

    return greetings[countryCode] || 'Hello';
}
```

## Method 2: Browser Language Detection

```javascript
function getGreetingByLanguage() {
    const language = navigator.language || navigator.userLanguage;
    const langCode = language.split('-')[0].toUpperCase();

    const greetingMap = {
        'JA': 'Konnichiwa',
        'PT': 'Olá',
        'FR': 'Bonjour',
        'DE': 'Hallo',
        'ES': 'Hola',
        'IT': 'Ciao',
        'RU': 'Privet',
        'ZH': 'Nǐ hǎo',
        'KO': 'Annyeonghaseyo',
        'SA': 'As-salamu alaykum',
        'HI': 'Namaste'
    };

    return greetingMap[langCode] || 'Hello';
}
```

## Method 3: Time-Based Greeting (Universal)

```javascript
function getTimeBasedGreeting() {
    const hour = new Date().getHours();

    if (hour >= 5 && hour < 12) {
        return 'Good morning';
    } else if (hour >= 12 && hour < 17) {
        return 'Good afternoon';
    } else if (hour >= 17 && hour < 21) {
        return 'Good evening';
    } else {
        return 'Good night';
    }
}
```

## Complete Solution (Recommended)

```javascript
class InternationalGreeting {
    constructor() {
        this.greetings = {
            'JP': { native: 'こんにちは', romaji: 'Konnichiwa' },
            'BR': { native: 'Olá', romaji: null },
            'FR': { native: 'Bonjour', romaji: null },
            'DE': { native: 'Hallo', romaji: null },
            'ES': { native: 'Hola', romaji: null },
            'IT': { native: 'Ciao', romaji: null },
            'RU': { native: 'Привет', romaji: 'Privet' },
            'CN': { native: '你好', romaji: 'Nǐ hǎo' },
            'KR': { native: '안녕하세요', romaji: 'Annyeonghaseyo' },
            'SA': { native: 'السلام عليكم', romaji: 'As-salamu alaykum' },
            'IN': { native: 'नमस्ते', romaji: 'Namaste' }
        };
    }

    async getLocationGreeting() {
        try {
            const response = await fetch('https://ipapi.co/json/', { timeout: 5000 });
            const data = await response.json();
            const country = this.greetings[data.country_code];

            if (country) {
                return country.native;
            }
        } catch (error) {
            console.warn('Location detection failed:', error);
        }

        // Fallback to language detection
        return this.getLanguageGreeting();
    }

    getLanguageGreeting() {
        const language = (navigator.language || navigator.userLanguage).split('-')[0].toUpperCase();
        const langMap = {
            'JA': 'こんにちは',
            'PT': 'Olá',
            'FR': 'Bonjour',
            'DE': 'Hallo',
            'ES': 'Hola',
            'IT': 'Ciao',
            'RU': 'Привет',
            'ZH': '你好',
            'KO': '안녕하세요',
            'AR': 'السلام عليكم',
            'HI': 'नमस्ते'
        };

        return langMap[language] || 'Hello';
    }
}

// Usage
const greeter = new InternationalGreeting();
greeter.getLocationGreeting().then(greeting => {
    console.log(`Welcome! ${greeting}`);
});
```

## Alternative Free APIs

If `ipapi.co` doesn't work, try these free alternatives:
- `https://ipinfo.io/json`
- `https://api.myip.com`

## Privacy Note

For privacy-conscious applications, consider asking users directly:
```html
<select id="languagePreference" onchange="updateGreeting()">
    <option value="en">English - Hello</option>
    <option value="es">Spanish - Hola</option>
    <option value="fr">French - Bonjour</option>
    <!-- Add more options -->
</select>
```

The IP-based approach requires no user input but may be less accurate. Combine methods for best results - use time-based greetings as your universal fallback.

