```javascript
function getGreetingByLanguage() {
    const language = navigator.language || navigator.userLanguage;
    const langCode = language.split('-')[0].toUpperCase();

    const greetingMap = {
        'JA': 'Konnichiwa',
        'PT': 'Olá',
        'FR': 'Bonjour',
        'DE': 'Hallo',
        'ES': 'Hola',
        'IT': 'Ciao',
        'RU': 'Privet',
        'ZH': 'Nǐ hǎo',
        'KO': 'Annyeonghaseyo',
        'SA': 'As-salamu alaykum',
        'HI': 'Namaste'
    };

    return greetingMap[langCode] || 'Hello';
}
```

## Method 3: Time-Based Greeting (Universal)

```javascript
function getTimeBasedGreeting() {
    const hour = new Date().getHours();

    if (hour >= 5 && hour < 12) {
        return 'Good morning';
    } else if (hour >= 12 && hour < 17) {
        return 'Good afternoon';
    } else if (hour >= 17 && hour < 21) {
        return 'Good evening';
    } else {
        return 'Good night';
    }
}
```

## Complete Solution (Recommended)

```javascript
class InternationalGreeting {
    constructor() {
        this.greetings = {
            'JP': { native: 'こんにちは', romaji: 'Konnichiwa' },
            'BR': { native: 'Olá', romaji: null },
            'FR': { native: 'Bonjour', romaji: null },
            'DE': { native: 'Hallo', romaji: null },
            'ES': { native: 'Hola', romaji: null },
            'IT': { native: 'Ciao', romaji: null },
            'RU': { native: 'Привет', romaji: 'Privet' },
            'CN': { native: '你好', romaji: 'Nǐ hǎo' },
            'KR': { native: '안녕하세요', romaji: 'Annyeonghaseyo' },
            'SA': { native: 'السلام عليكم', romaji: 'As-salamu alaykum' },
            'IN': { native: 'नमस्ते', romaji: 'Namaste' }
        };
    }

    async getLocationGreeting() {
        try {
            const response = await fetch('https://ipapi.co/json/', { timeout: 5000 });
            const data = await response.json();
            const country = this.greetings[data.country_code];

            if (country) {
                return country.native;
            }
        } catch (error) {
            console.warn('Location detection failed:', error);
        }

        // Fallback to language detection
        return this.getLanguageGreeting();
    }

