Here's an HTML/CSS/JS solution that creates an animated text display for your company name with a large font size:

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Company Name Animation</title>
    <style>
        body {
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            margin: 0;
            background: linear-gradient(135deg, #1a2a6c, #b21f1f, #fdbb2d);
            overflow: hidden;
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
        }

        .company-name {
            font-size: 5rem;
            font-weight: 800;
            color: white;
            text-shadow: 
                0 0 10px rgba(255, 255, 255, 0.7),
                0 0 20px rgba(255, 255, 255, 0.5),
                0 0 30px rgba(255, 255, 255, 0.3);
            position: relative;
            letter-spacing: 3px;

            /* Animation properties */
            animation: 
                pulseGlow 2s ease-in-out infinite,
                float 4s ease-in-out infinite;
        }

        @keyframes pulseGlow {
            0% { text-shadow: 
                0 0 10px rgba(255, 255, 255, 0.7),
                0 0 20px rgba(255, 255, 255, 0.5),
                0 0 30px rgba(255, 255, 255, 0.3);
            }
            50% { text-shadow: 
                0 0 20px rgba(255, 255, 255, 0.9),
                0 0 40px rgba(255, 255, 255, 0.7),
                0 0 60px rgba(255, 255, 255, 0.5);
            }
            100% { text-shadow: 
                0 0 10px rgba(255, 255, 255, 0.7),
                0 0 20px rgba(255, 255, 255, 0.5),
                0 0 30px rgba(255, 255, 255, 0.3);
            }
        }

        @keyframes float {
            0% { transform: translateY(0); }
            50% { transform: translateY(-20px); }
            100% { transform: translateY(0); }
        }

        /* Responsive design */
        @media (max-width: 768px) {
            .company-name {
                font-size: 3rem;
            }
        }
    </style>
</head>
<body>
    <div class="company-name">Your Company Name</div>

    <script>
        // Optional: Dynamic text replacement
        document.addEventListener('DOMContentLoaded', function() {
            const companyElements = document.querySelectorAll('.company-name');
            companyElements.forEach(el => {
                el.textContent = 'Your Company Name'; // Replace with actual company name
            });
        });
    </script>
</body>
</html>
```

